from typing import Literal

from fastapi import FastAPI, HTTPException, Query
from pydantic import BaseModel, Field

app = FastAPI(title="Envíos de práctica", version="0.1.0")


class EnvioNuevo(BaseModel):
    destino: str = Field(min_length=3, max_length=60)
    peso_kg: float = Field(gt=0, le=1000)
    prioridad: Literal["normal", "urgente"] = "normal"


class Envio(EnvioNuevo):
    id: int
    estado: Literal["pendiente", "en_ruta", "entregado"] = "pendiente"


ENVIOS: dict[int, Envio] = {}


@app.post("/envios", response_model=Envio, status_code=201)
def crear(nuevo: EnvioNuevo) -> Envio:
    envio = Envio(id=len(ENVIOS) + 1, **nuevo.model_dump())
    ENVIOS[envio.id] = envio
    return envio


@app.get("/envios/{envio_id}", response_model=Envio)
def uno(envio_id: int) -> Envio:
    if envio_id not in ENVIOS:
        raise HTTPException(status_code=404, detail="No existe ese envío")
    return ENVIOS[envio_id]


@app.get("/envios", response_model=list[Envio])
def listar(
    estado: Literal["pendiente", "en_ruta", "entregado"] | None = None,
    limite: int = Query(10, ge=1, le=100),
) -> list[Envio]:
    todos = [e for e in ENVIOS.values() if estado is None or e.estado == estado]
    return todos[:limite]

