from django.contrib import admin

from .models import Envio


@admin.register(Envio)
class EnvioAdmin(admin.ModelAdmin):
    list_display = ("id", "destino", "peso_kg", "prioridad", "estado")
    list_filter = ("estado", "prioridad")

@csrf_exempt  # solo para la demo con curl; una API real decide su política de CSRF
@require_http_methods(["GET", "POST"])
def envios(request):
    if request.method == "GET":
        qs = Envio.objects.all()
        if estado := request.GET.get("estado"):
            qs = qs.filter(estado=estado)
        return JsonResponse([como_dict(e) for e in qs[:10]], safe=False)
    datos = json.loads(request.body)
    envio = Envio(destino=datos.get("destino", ""), peso_kg=datos.get("peso_kg", 0),
                  prioridad=datos.get("prioridad", "normal"))
    try:
        envio.full_clean()
    except ValidationError as err:
        return JsonResponse(err.message_dict, status=400)
    envio.save()
    return JsonResponse(como_dict(envio), status=201)

